// ─── Exports ──────────────────────────────────────────────────────────────────

export const DICTIONARY_WORDS: Record<string, DictionaryWord[]> = { fr: FR, es: ES, en: EN };

export function getWordsByLanguage(language: string): DictionaryWord[] {
  return DICTIONARY_WORDS[language] ?? DICTIONARY_WORDS.fr;
}

export function getWordById(id: string): DictionaryWord | undefined {
  for (const words of Object.values(DICTIONARY_WORDS)) {
    const found = words.find((w) => w.id === id);
    if (found) return found;
  }
  return undefined;
}
